func PathWritingModeCustom(s string) PathWritingMode {
	return PathWritingMode(s)
}

// XmlLang sets the "xml:lang" attribute.
//
// Deprecated: the "xml:lang" attribute is deprecated or obsolete in its source specification.
func (e *PathElement) XmlLang(s string) *PathElement {
	e.attributes.Set("xml:lang", s)

	return e
}

// XmlSpace sets the "xml:space" attribute.
//
// Deprecated: the "xml:space" attribute is deprecated or obsolete in its source specification.
func (e *PathElement) XmlSpace(a PathXmlSpace) *PathElement {
	e.attributes.Set("xml:space", string(a))

	return e
}

// Render writes the opening tag and its attributes, then renders each child, then writes the closing tag.
//
// Output is written directly to w as many small writes, with no intermediate buffering.
// Pass a buffered writer, or use htemel.Render, when w is expensive to write to.
func (e *PathElement) Render(w io.Writer) error {
	if e.skipRender {
		return nil
	}

	if e.attributes.Len() == 0 {
		if _, err := io.WriteString(w, "<path>"); err != nil {
			return err
		}
	} else {
		if _, err := io.WriteString(w, "<path"); err != nil {
			return err
		}
		if _, err := e.attributes.WriteTo(w); err != nil {
			return err
		}
		if _, err := io.WriteString(w, ">"); err != nil {
			return err
		}
	}

	for _, child := range e.children {
		if err := child.Render(w); err != nil {
			return err
		}
	}

	_, err := io.WriteString(w, "</path>")
	return err
}
